/** Raw PTY bytes (`Channel<tauri::ipc::Response>` → ArrayBuffer, §5). */
export type PtyOutput = (chunk: ArrayBuffer) => void;
export type OnProgress = (p: LaunchProgress) => void;
export type OnSignProgress = (p: SignProgress) => void;

/** §6 events: identifiers and revisions only. The payload types are generated from Rust. */
export interface EventPayloads {
	'project:changed': ProjectChanged;
	'projects:changed': ProjectsChanged;
	'packet:changed': PacketChanged;
	'decision:pending': DecisionPending;
	'tamper:detected': TamperDetected;
	'run:status': RunStatusChanged;
	'config:changed': ConfigChanged;
	'doctor:status': DoctorStatus;
	'settings:changed': SettingsChanged;
}
export type EventName = keyof EventPayloads;
export const EVENT_NAMES = [
	'project:changed',
	'projects:changed',
	'packet:changed',
	'decision:pending',
	'tamper:detected',
	'run:status',
	'config:changed',
	'doctor:status',
	'settings:changed'
] as const satisfies readonly EventName[];
export type Unlisten = () => void;
